    static prepareLineItem({
        total,
        dimensionType,
        dimensionUnit,
        dimensionName,
        dimensionId,
        offeringName,
        usageIncrement,
        negative,
        tieredName,
    }: {
        total: number;
        dimensionType: string;
        dimensionName: string;
        dimensionUnit: string;
        dimensionId: string;
        offeringName: string;
        usageIncrement: number;
        negative?: boolean;
        tieredName?: string;
    }): { total: number; dimension: string; unit?: string; displayName: string } {
        const timeBasedUnits = {
            second: {
                60: 'minute',
                3600: 'hour',
                86400: 'day',
            },
            minute: { 60: 'hour', 1440: 'day' },
            hour: { 24: 'day' },
        };
        const dataBasedUnits = {
            byte: {
                1024: 'kibibyte',
                1000: 'kilobyte',
                1048576: 'mebibyte',
                1000000: 'megabyte',
                1073741824: 'gibibyte',
