  }
  console.log("\n--- EXPECTED SES ---");
  for(let i=0;i<expectedSes.length;i++) {
    console.log(`EXP ${i}: to=${expectedSes[i].to} source=${expectedSes[i].source} subj=${expectedSes[i].subject.data} bodyType=${expectedSes[i].html?'html':expectedSes[i].text?'text':'none'} replyTo=${expectedSes[i].replyTo}`);
  }

  // compare
  let ok = true;
  if (outbox.length !== expectedSes.length) {
    console.log(`FAIL: length mismatch ${outbox.length} vs ${expectedSes.length}`);
    ok=false;
  } else {
    for(let i=0;i<expectedSes.length;i++) {
      const exp = expectedSes[i];
      const got = outbox[i];
      if (JSON.stringify(exp.to) !== JSON.stringify(got.to)) { console.log(`FAIL index ${i} to mismatch`); ok=false; }
      if (exp.source !== got.source) { console.log(`FAIL index ${i} source mismatch exp=${exp.source} got=${got.source}`); ok=false; }
      if (exp.subject.data !== got.subject.data) { console.log(`FAIL subject ${i}`); ok=false; }
      if (exp.subject.charset !== got.subject.charset) { console.log(`FAIL subject charset ${i}`); ok=false; }
      // check body
      const expHtml = exp.html?.data; const gotHtml = got.html?.data;
      const expText = exp.text?.data; const gotText = got.text?.data;
      if (expHtml !== gotHtml) { console.log(`FAIL html ${i} exp=${expHtml} got=${gotHtml}`); ok=false; }
      if (expText !== gotText) { console.log(`FAIL text ${i} exp=${expText} got=${gotText}`); ok=false; }
      if (JSON.stringify(exp.replyTo) !== JSON.stringify(got.replyTo)) { console.log(`FAIL replyTo ${i} exp=${exp.replyTo} got=${got.replyTo}`); ok=false; }
      if (exp.configurationSet !== got.configurationSet) { console.log(`FAIL config ${i}`); ok=false; }
    }
  }
  console.log(ok ? "PASS: all matched" : "FAIL: mismatch");
}

main().catch(e=>{ console.error(e); process.exit(1) });
